// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address, uint256 value) public {
        uint256 before = c.depositsCount();
        (bool success, ) = address(c).call{value: value}("");
        if (!success) return; // skip reverts
        c.sendMoney(address(0), 0, ""); // no ETH sent, so receive not triggered
        assertTrue(c.depositsCount() == before + 1); // only the initial receive() added 1
    }
}

